#!/usr/bin/env python3
"""RET-04: disk-backed prefilter before active graph loading."""
from __future__ import annotations
import hashlib,importlib.metadata,json,platform,resource,time,tracemalloc
from datetime import datetime,timezone
from pathlib import Path
import duckdb,networkx as nx,polars as pl,pyarrow as pa,pyarrow.parquet as pq,rustworkx as rx
P=Path(__file__).resolve().parent;ROOT=P.parent.parent;OUT=P/'output';TOTAL=5000
def rss_bytes():
 for line in Path('/proc/self/status').read_text().splitlines():
  if line.startswith('VmRSS:'):return int(line.split()[1])*1024
 raise RuntimeError('VmRSS unavailable')
def fragment(i,match):
 g=nx.DiGraph()
 if match:
  g.add_node(f'p{i}',kind='person');g.add_node(f'e{i}',kind='event',lemma='greet');g.add_node(f'c{i}',kind='context',topic='opening');g.add_edge(f'p{i}',f'e{i}',relation='agent');g.add_edge(f'e{i}',f'c{i}',relation='in_context')
 else:g.add_node(f'n{i}',kind='noise',value=i)
 return json.dumps(nx.node_link_data(g,edges='edges'),sort_keys=True,separators=(',',':'))
def verify(data):
 g=nx.node_link_graph(json.loads(data),edges='edges');r=rx.PyDiGraph();idx={n:r.add_node(a) for n,a in g.nodes(data=True)}
 for a,b,d in g.edges(data=True):r.add_edge(idx[a],idx[b],d)
 edge_data=[r.get_edge_data_by_index(i) for i in r.edge_indices()]
 return any(a.get('kind')=='event' and a.get('lemma')=='greet' for a in r.nodes()) and any(e.get('relation')=='in_context' for e in edge_data)
def main():
 OUT.mkdir(parents=True,exist_ok=True);stats=[];fragments=[]
 for i in range(TOTAL):
  match=i%137==0;stats.append({'graph_id':f'g{i:05d}','ordinal':i,'has_greet_event':match,'has_opening_context':match,'has_agent_relation':match});fragments.append({'graph_id':f'g{i:05d}','graph_json':fragment(i,match)})
 pq.write_table(pa.Table.from_pylist(stats),OUT/'graph-stats.parquet',compression='zstd');pq.write_table(pa.Table.from_pylist(fragments),OUT/'graph-fragments.parquet',compression='zstd')
 db=OUT/'ret-04.duckdb'
 if db.exists():db.unlink()
 con=duckdb.connect(str(db));sp=str((OUT/'graph-stats.parquet').resolve());fp=str((OUT/'graph-fragments.parquet').resolve());sp_sql=sp.replace("'","''");fp_sql=fp.replace("'","''");con.execute(f"CREATE VIEW stats AS SELECT * FROM read_parquet('{sp_sql}')");con.execute(f"CREATE VIEW fragments AS SELECT * FROM read_parquet('{fp_sql}')")
 measurements=[]
 for size in (100,1000,5000):
  rss_before=rss_bytes();tracemalloc.start();start=time.perf_counter_ns();ids=[r[0] for r in con.execute('SELECT graph_id FROM stats WHERE ordinal < ? AND has_greet_event AND has_opening_context AND has_agent_relation ORDER BY graph_id',[size]).fetchall()];prefilter_ns=time.perf_counter_ns()-start;_,prefilter_peak=tracemalloc.get_traced_memory();tracemalloc.stop();rss_after_prefilter=rss_bytes()
  tracemalloc.start();start=time.perf_counter_ns();loaded=con.execute('SELECT graph_id,graph_json FROM fragments WHERE graph_id IN (SELECT unnest(?)) ORDER BY graph_id',[ids]).fetchall();load_ns=time.perf_counter_ns()-start;_,load_peak=tracemalloc.get_traced_memory();tracemalloc.stop();verified=[gid for gid,data in loaded if verify(data)];rss_after_active=rss_bytes()
  measurements.append({'collection_size':size,'candidate_ids':ids,'candidate_count':len(ids),'fragment_count_loaded':len(loaded),'verified_match_count':len(verified),'prefilter_latency_ns':prefilter_ns,'fragment_load_and_verify_latency_ns':load_ns,'prefilter_python_peak_bytes':prefilter_peak,'active_fragment_python_peak_bytes':load_peak,'rss_before_bytes':rss_before,'rss_after_prefilter_bytes':rss_after_prefilter,'rss_after_active_verification_bytes':rss_after_active,'collection_fraction_loaded':len(loaded)/size})
 plan='\n'.join(f'{r[0]}\n{r[1]}' for r in con.execute(f"EXPLAIN SELECT f.graph_id,f.graph_json FROM read_parquet('{fp_sql}') f JOIN read_parquet('{sp_sql}') s USING(graph_id) WHERE s.has_greet_event AND s.has_opening_context AND s.has_agent_relation").fetchall())
 polars_ids=(pl.scan_parquet(sp).filter(pl.col('has_greet_event') & pl.col('has_opening_context') & pl.col('has_agent_relation')).select('graph_id').sort('graph_id').collect(engine='streaming').get_column('graph_id').to_list());con.close()
 full_json_bytes=sum(len(r['graph_json'].encode()) for r in fragments);loaded_ids=set(measurements[-1]['candidate_ids']);loaded_json_bytes=sum(len(r['graph_json'].encode()) for r in fragments if r['graph_id'] in loaded_ids)
 graph03_path=ROOT/'poc/graph-03/output/results.json';graph03_payload_path=ROOT/'poc/graph-03/output/candidate-payloads.parquet';ret02_path=ROOT/'poc/ret-02/output/results.json'
 graph03=json.loads(graph03_path.read_text());ret02=json.loads(ret02_path.read_text());active=nx.node_link_graph(graph03['graph'],edges='edges');wanted_poc=ret02['integrated_graph03']['full_example']['source_poc'];candidate_nodes=[n for n,d in active.nodes(data=True)if d['node_type']=='candidate'];integrated_stats=[]
 for candidate_id in candidate_nodes:
  outgoing=list(active.out_edges(candidate_id,data=True));incoming=list(active.in_edges(candidate_id,data=True));support_id=next(t for _,t,d in outgoing if d['edge_type']=='supported_by');group_id=next(t for _,t,d in outgoing if d['edge_type']=='member_of');conflicts=sum(d['edge_type']=='conflicts_with'for *_,d in outgoing)+sum(d['edge_type']=='conflicts_with'for *_,d in incoming);integrated_stats.append({'candidate_id':candidate_id,'group_id':group_id,'source_poc':active.nodes[support_id]['poc_id'],'conflict_count':conflicts,'payload_sha256':active.nodes[candidate_id]['payload_sha256']})
 integrated_stats_path=OUT/'integrated-candidate-stats.parquet';pq.write_table(pa.Table.from_pylist(integrated_stats),integrated_stats_path,compression='zstd');icon=duckdb.connect();stats_actual=str(integrated_stats_path.resolve());payload_actual=str(graph03_payload_path.resolve());selected_ids=[row[0]for row in icon.execute('SELECT candidate_id FROM read_parquet(?) WHERE source_poc=? AND conflict_count>0 ORDER BY candidate_id',[stats_actual,wanted_poc]).fetchall()];integrated_loaded=icon.execute('SELECT candidate_id,payload_json,sha256 FROM read_parquet(?) WHERE candidate_id IN (SELECT unnest(?)) ORDER BY candidate_id',[payload_actual,selected_ids]).fetchall();integrated_plan='\n'.join(f'{row[0]}\n{row[1]}'for row in icon.execute("EXPLAIN SELECT candidate_id,payload_json FROM read_parquet(?) WHERE candidate_id IN (SELECT unnest(?))",[payload_actual,selected_ids]).fetchall());icon.close();stats_by_id={row['candidate_id']:row for row in integrated_stats};integrated_verified=all(hashlib.sha256(payload.encode()).hexdigest()==sha==stats_by_id[cid]['payload_sha256']for cid,payload,sha in integrated_loaded)
 validations={'all_candidates_verified':all(m['candidate_count']==m['verified_match_count'] for m in measurements),'never_loaded_entire_collection':all(m['fragment_count_loaded']<m['collection_size'] for m in measurements),'selection_before_fragment_load':True,'largest_loaded_fraction_below_one_percent':measurements[-1]['collection_fraction_loaded']<.01,'loaded_bytes_below_full_bytes':loaded_json_bytes<full_json_bytes,'duckdb_polars_candidate_ids_equal':polars_ids==measurements[-1]['candidate_ids'],'query_plan_captured':bool(plan) and 'READ_PARQUET' in plan and 'Filters:' in plan,'integrated_prefilter_before_payload_load':0<len(integrated_loaded)==len(selected_ids)<len(candidate_nodes),'integrated_payload_hashes_verified':integrated_verified,'integrated_query_plan_captured':'READ_PARQUET'in integrated_plan};assert all(validations.values())
 process_peak_rss=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss*1024
 result={'measurements':measurements,'largest_run_bytes':{'all_fragment_json_bytes':full_json_bytes,'loaded_fragment_json_bytes':loaded_json_bytes},'polars_streaming_candidate_ids':polars_ids,'duckdb_query_plan':plan,'integrated_graph03':{'graph03_result_sha256':hashlib.sha256(graph03_path.read_bytes()).hexdigest(),'ret02_result_sha256':hashlib.sha256(ret02_path.read_bytes()).hexdigest(),'selected_source_poc':wanted_poc,'collection_candidate_count':len(candidate_nodes),'prefiltered_candidate_ids':selected_ids,'loaded_payload_count':len(integrated_loaded),'loaded_payload_json_bytes':sum(len(payload.encode())for _,payload,_ in integrated_loaded),'payload_parquet_bytes':graph03_payload_path.stat().st_size,'query_plan':integrated_plan},'process_peak_rss_bytes':process_peak_rss,'validation':validations};(OUT/'results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');last=measurements[-1];summary={'largest_collection_size':TOTAL,'largest_candidate_count':last['candidate_count'],'largest_fragment_count_loaded':last['fragment_count_loaded'],'largest_collection_fraction_loaded':last['collection_fraction_loaded'],'all_fragment_json_bytes':full_json_bytes,'loaded_fragment_json_bytes':loaded_json_bytes,'integrated_graph03_collection_candidates':len(candidate_nodes),'integrated_graph03_loaded_payloads':len(integrated_loaded),'process_peak_rss_bytes':process_peak_rss,'verdict':'GO_DISK_PREFILTER_BEFORE_ACTIVE_GRAPH_LOADING'};(OUT/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');(OUT/'versions-and-parameters.json').write_text(json.dumps({'generated_at':datetime.now(timezone.utc).isoformat(),'platform':platform.platform(),'duckdb':importlib.metadata.version('duckdb'),'polars':importlib.metadata.version('polars'),'pyarrow':importlib.metadata.version('pyarrow'),'rustworkx':importlib.metadata.version('rustworkx'),'memory_scope':'Python tracemalloc plus Linux /proc VmRSS checkpoints and whole-process ru_maxrss including native allocations'},indent=2)+'\n');print(f"RET-04: synthetic {last['fragment_count_loaded']}/{TOTAL}; GRAPH-03 {len(integrated_loaded)}/{len(candidate_nodes)} payloads loaded; GO")
if __name__=='__main__':main()
